class Solution {
    private java.util.TreeMap<Integer, Integer> lower;
    private java.util.TreeMap<Integer, Integer> upper;
    private int lowerSize;
    private int upperSize;

    public double[] medianSlidingWindow(int[] nums, int k) {
        lower = new java.util.TreeMap<>();
        upper = new java.util.TreeMap<>();
        lowerSize = 0;
        upperSize = 0;
        double[] result = new double[nums.length - k + 1];
        for (int i = 0; i < nums.length; i++) {
            addValue(nums[i]);
            if (i >= k) {
                removeValue(nums[i - k]);
            }
            if (i >= k - 1) {
                result[i - k + 1] = median(k);
            }
        }
        return result;
    }

    private void addValue(int value) {
        if (lowerSize == 0 || value <= lower.lastKey()) {
            addOne(lower, value);
            lowerSize++;
        } else {
            addOne(upper, value);
            upperSize++;
        }
        rebalance();
    }

    private void removeValue(int value) {
        if (lower.containsKey(value)) {
            removeOne(lower, value);
            lowerSize--;
        } else {
            removeOne(upper, value);
            upperSize--;
        }
        rebalance();
    }

    private void rebalance() {
        while (lowerSize > upperSize + 1) {
            int value = lower.lastKey();
            removeOne(lower, value);
            addOne(upper, value);
            lowerSize--;
            upperSize++;
        }
        while (lowerSize < upperSize) {
            int value = upper.firstKey();
            removeOne(upper, value);
            addOne(lower, value);
            upperSize--;
            lowerSize++;
        }
    }

    private double median(int k) {
        if ((k & 1) == 1) {
            return lower.lastKey();
        }
        return ((long) lower.lastKey() + upper.firstKey()) / 2.0;
    }

    private void addOne(java.util.TreeMap<Integer, Integer> map, int value) {
        map.put(value, map.getOrDefault(value, 0) + 1);
    }

    private void removeOne(java.util.TreeMap<Integer, Integer> map, int value) {
        int count = map.get(value);
        if (count == 1) {
            map.remove(value);
        } else {
            map.put(value, count - 1);
        }
    }
}

class Solution {
    private java.util.PriorityQueue<Integer> small;
    private java.util.PriorityQueue<Integer> large;
    private java.util.Map<Integer, Integer> delayed;
    private int smallSize;
    private int largeSize;

    public double[] medianSlidingWindow(int[] nums, int k) {
        small = new java.util.PriorityQueue<>(java.util.Collections.reverseOrder());
        large = new java.util.PriorityQueue<>();
        delayed = new java.util.HashMap<>();
        smallSize = 0;
        largeSize = 0;
        double[] result = new double[nums.length - k + 1];
        for (int i = 0; i < nums.length; i++) {
            add(nums[i]);
            if (i >= k) {
                erase(nums[i - k]);
            }
            if (i >= k - 1) {
                result[i - k + 1] = median(k);
            }
        }
        return result;
    }

    private void add(int value) {
        if (small.isEmpty() || value <= small.peek()) {
            small.offer(value);
            smallSize++;
        } else {
            large.offer(value);
            largeSize++;
        }
        rebalance();
    }

    private void erase(int value) {
        delayed.put(value, delayed.getOrDefault(value, 0) + 1);
        if (!small.isEmpty() && value <= small.peek()) {
            smallSize--;
            if (value == small.peek()) {
                prune(small);
            }
        } else {
            largeSize--;
            if (!large.isEmpty() && value == large.peek()) {
                prune(large);
            }
        }
        rebalance();
    }

    private void rebalance() {
        if (smallSize > largeSize + 1) {
            large.offer(small.poll());
            smallSize--;
            largeSize++;
            prune(small);
        } else if (smallSize < largeSize) {
            small.offer(large.poll());
            smallSize++;
            largeSize--;
            prune(large);
        }
    }

    private void prune(java.util.PriorityQueue<Integer> heap) {
        while (!heap.isEmpty()) {
            int value = heap.peek();
            int count = delayed.getOrDefault(value, 0);
            if (count == 0) {
                break;
            }
            if (count == 1) {
                delayed.remove(value);
            } else {
                delayed.put(value, count - 1);
            }
            heap.poll();
        }
    }

    private double median(int k) {
        if ((k & 1) == 1) {
            return small.peek();
        }
        return ((long) small.peek() + large.peek()) / 2.0;
    }
}

class Solution {
    private int[] values;
    private Fenwick fenwick;

    public double[] medianSlidingWindow(int[] nums, int k) {
        values = compressedValues(nums);
        fenwick = new Fenwick(values.length);
        double[] result = new double[nums.length - k + 1];
        for (int i = 0; i < nums.length; i++) {
            fenwick.add(indexOf(nums[i]), 1);
            if (i >= k) {
                fenwick.add(indexOf(nums[i - k]), -1);
            }
            if (i >= k - 1) {
                result[i - k + 1] = median(k);
            }
        }
        return result;
    }

    private double median(int k) {
        if ((k & 1) == 1) {
            return values[fenwick.select(k / 2 + 1) - 1];
        }
        int left = values[fenwick.select(k / 2) - 1];
        int right = values[fenwick.select(k / 2 + 1) - 1];
        return ((long) left + right) / 2.0;
    }

    private int indexOf(int value) {
        return java.util.Arrays.binarySearch(values, value) + 1;
    }

    private int[] compressedValues(int[] nums) {
        int[] sorted = java.util.Arrays.copyOf(nums, nums.length);
        java.util.Arrays.sort(sorted);
        int size = 0;
        for (int value : sorted) {
            if (size == 0 || sorted[size - 1] != value) {
                sorted[size++] = value;
            }
        }
        return java.util.Arrays.copyOf(sorted, size);
    }

    private static class Fenwick {
        private final int[] tree;

        Fenwick(int size) {
            tree = new int[size + 1];
        }

        void add(int index, int delta) {
            for (int i = index; i < tree.length; i += i & -i) {
                tree[i] += delta;
            }
        }

        int select(int order) {
            int index = 0;
            for (int step = Integer.highestOneBit(tree.length - 1); step > 0; step >>= 1) {
                int next = index + step;
                if (next < tree.length && tree[next] < order) {
                    index = next;
                    order -= tree[next];
                }
            }
            return index + 1;
        }
    }
}

class Solution {
    public double[] medianSlidingWindow(int[] nums, int k) {
        java.util.ArrayList<Integer> window = new java.util.ArrayList<>();
        double[] result = new double[nums.length - k + 1];
        for (int i = 0; i < nums.length; i++) {
            int insertAt = java.util.Collections.binarySearch(window, nums[i]);
            if (insertAt < 0) {
                insertAt = -insertAt - 1;
            }
            window.add(insertAt, nums[i]);
            if (window.size() > k) {
                int removeAt = java.util.Collections.binarySearch(window, nums[i - k]);
                window.remove(removeAt);
            }
            if (i >= k - 1) {
                if ((k & 1) == 1) {
                    result[i - k + 1] = window.get(k / 2);
                } else {
                    result[i - k + 1] = ((long) window.get(k / 2 - 1) + window.get(k / 2)) / 2.0;
                }
            }
        }
        return result;
    }
}

class Solution {
    private int[] values;
    private java.util.TreeSet<Integer> lower;
    private java.util.TreeSet<Integer> upper;

    public double[] medianSlidingWindow(int[] nums, int k) {
        values = nums;
        java.util.Comparator<Integer> byValueThenIndex = (a, b) -> {
            int cmp = Integer.compare(values[a], values[b]);
            return cmp != 0 ? cmp : Integer.compare(a, b);
        };
        lower = new java.util.TreeSet<>(byValueThenIndex);
        upper = new java.util.TreeSet<>(byValueThenIndex);
        double[] result = new double[nums.length - k + 1];
        for (int i = 0; i < nums.length; i++) {
            addIndex(i);
            if (i >= k) {
                removeIndex(i - k);
            }
            if (i >= k - 1) {
                result[i - k + 1] = median(k);
            }
        }
        return result;
    }

    private void addIndex(int index) {
        if (lower.isEmpty() || compare(index, lower.last()) <= 0) {
            lower.add(index);
        } else {
            upper.add(index);
        }
        rebalance();
    }

    private void removeIndex(int index) {
        if (!lower.remove(index)) {
            upper.remove(index);
        }
        rebalance();
    }

    private void rebalance() {
        while (lower.size() > upper.size() + 1) {
            upper.add(lower.pollLast());
        }
        while (lower.size() < upper.size()) {
            lower.add(upper.pollFirst());
        }
    }

    private double median(int k) {
        if ((k & 1) == 1) {
            return values[lower.last()];
        }
        return ((long) values[lower.last()] + values[upper.first()]) / 2.0;
    }

    private int compare(int a, int b) {
        int cmp = Integer.compare(values[a], values[b]);
        return cmp != 0 ? cmp : Integer.compare(a, b);
    }
}
